        "Aprobadores de COORDINACIÓN GENERAL DE LA ALCALDÍA", "Aprobadores de CULTURA, TURISMO Y DEPORTE",
        "Aprobadores de DE PORTAVOZ, SEGURIDAD Y EMERGENCIAS", "Aprobadores de DESARROLLO URBANO",
        "Aprobadores de ECONOMÍA, INNOVACIÓN Y EMPLEO", "Aprobadores de EMPRESA MUNICIPAL DE TRANSPORTES DE MADRID, S.A. (EMT)",
        "Aprobadores de FAMILIAS, IGUALDAD Y BIENESTAR SOCIAL", "Aprobadores de FUENCARRAL - EL PARDO",
        "Aprobadores de HACIENDA Y PERSONAL", "Aprobadores de HORTALEZA",
        "Aprobadores de INFORMÁTICA DEL AYUNTAMIENTO DE MADRID", "Aprobadores de LATINA",
        "Aprobadores de MADRID CALLE 30, S.A.", "Aprobadores de MADRID DESTINO CULTURA TURISMO Y NEGOCIO, S.A.",
        "Aprobadores de MADRID SALUD", "Aprobadores de MEDIO AMBIENTE Y MOVILIDAD",
        "Aprobadores de MERCAMADRID", "Aprobadores de MONCLOA - ARAVACA",
        "Aprobadores de MORATALAZ", "Aprobadores de OBRAS Y EQUIPAMIENTOS",
        "Aprobadores de PRESIDENCIA DEL PLENO", "Aprobadores de PUENTE DE VALLECAS",
        "Aprobadores de RETIRO", "Aprobadores de SALAMANCA",
        "Aprobadores de SAN BLAS - CANILLEJAS", "Aprobadores de SERVICIOS FUNERARIOS Y CEMENTERIOS DE MADRID, S.A.",
        "Aprobadores de USERA", "Aprobadores de VICÁLVARO", "Aprobadores de VILLAVERDE",
        "Aprobadores de VIVIENDA Y SUELO DE MADRID, S.A", "Validadores del ARGANZUELA",
        "Validadores del BARAJAS", "Validadores del CARABANCHEL", "Validadores del CENTRO",
        "Validadores del CHAMARTÍN", "Validadores del CHAMBERÍ", "Validadores del CIUDAD LINEAL",
        "Validadores del CLUB DE CAMPO VILLA DE MADRID, S.A.", "Validadores del COORDINACIÓN GENERAL DE LA ALCALDÍA",
        "Validadores del CULTURA, TURISMO Y DEPORTE", "Validadores del DE PORTAVOZ, SEGURIDAD Y EMERGENCIAS",
        "Validadores del DESARROLLO URBANO", "Validadores del ECONOMÍA, INNOVACIÓN Y EMPLEO",
        "Validadores del EMT", "Validadores del FAMILIAS, IGUALDAD Y BIENESTAR SOCIAL",
        "Validadores del FUENCARRAL - EL PARDO", "Validadores del HACIENDA Y PERSONAL",
        "Validadores del HORTALEZA", "Validadores del IAM", "Validadores del LATINA",
        "Validadores del MADRID CALLE 30, S.A.", "Validadores del MADRID DESTINO CULTURA TURISMO Y NEGOCIO, S.A.",
        "Validadores del MADRID SALUD", "Validadores del MEDIO AMBIENTE Y MOVILIDAD",
        "Validadores del MERCAMADRID", "Validadores del MONCLOA - ARAVACA",
        "Validadores del MORATALAZ", "Validadores del OBRAS Y EQUIPAMIENTOS",
        "Validadores del PRESIDENCIA DEL PLENO", "Validadores del PUENTE DE VALLECAS",
        "Validadores del RETIRO", "Validadores del SALAMANCA", "Validadores del SAN BLAS - CANILLEJAS",
        "Validadores del SERVICIOS FUNERARIOS Y CEMENTERIOS DE MADRID, S.A.", "Validadores del USERA",
        "Validadores del VICÁLVARO", "Validadores del VILLA DE VALLECAS", "Validadores del VILLAVERDE",
        "Validadores del VIVIENDA Y SUELO DE MADRID, S.A"
    ];

    var updatedCount = 0;
    var skippedCount = 0;

    for (var i = 0; i < groupNames.length; i++) {
        var gr = new GlideRecord('sys_user_group');
        if (gr.get('name', groupNames[i])) {

            var currentTypes = gr.getValue('type') || '';

            // Check if the type is already assigned to avoid duplicates
            if (currentTypes.indexOf(targetTypeId) === -1) {
                var newTypes = currentTypes ? currentTypes + ',' + targetTypeId : targetTypeId;

                gr.setWorkflow(false); // Fastest way: bypasses business rules
                gr.autoSysFields(false); // Keep the original system update fields
                gr.type = newTypes;
                gr.update();
                updatedCount++;
            } else {
                skippedCount++;
            }
        }
    }

    gs.info('Group Type Update Complete. Updated: ' + updatedCount + ', Skipped (already had type): ' + skippedCount);
})();
